package au.com.endurancecoach;
import au.com.endurancecoach.core.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.nio.charset.StandardCharsets;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class RouteSyncTest {
 private CoachRepository repo;
 @Before public void open(){repo=new CoachRepository(RuntimeEnvironment.getApplication());}
 @After public void close(){repo.close();}
 private JSONObject route()throws Exception{return RoutePlan.create("Park","imported",new JSONArray("[[-31.95,115.85],[-31.949,115.85]]"),new JSONArray(),"GPX","");}
 private JSONObject change()throws Exception{return RoutePlan.change("route:1","route",route(),false,null,1000);}
 private BridgeClient bridge(boolean supported,boolean ack){return new BridgeClient((m,u,h,b)->{try{JSONObject q=new JSONObject(new String(b,StandardCharsets.UTF_8)),snapshot=new JSONObject().put("plan",new JSONArray()),reply=new JSONObject().put("ok",true).put("snapshot",snapshot);if(supported){JSONArray changes=q.optJSONArray("route_changes");if(changes==null)changes=new JSONArray();snapshot.put("route_schema_version",1).put("route_changes",changes);JSONArray ids=new JSONArray();for(int i=0;i<changes.length();i++)if(ack)ids.put(changes.getJSONObject(i).getString("change_id"));reply.put("ack_routes",ids);}return new Transport.Response(200,reply.toString().getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new java.io.IOException(e);}},"https://script.google.com/macros/s/test/exec","synthetic-secret-12345678901234567890");}
 @Test public void offlineSaveSurvivesRestartAndOldServerKeepsQueue()throws Exception{repo.store.saveRouteChanges(new JSONArray().put(change()));repo.close();repo=new CoachRepository(RuntimeEnvironment.getApplication());repo.syncCloud(bridge(false,true));assertEquals(1,repo.store.pending("route").length());assertEquals(1,repo.store.routeRecords().length());assertTrue(repo.store.get("status").optString("route_error").contains("phone"));}
 @Test public void explicitAcknowledgementOnlyClearsSentImmutableIds()throws Exception{repo.store.saveRouteChanges(new JSONArray().put(change()));repo.syncCloud(bridge(true,false));assertEquals(1,repo.store.pending("route").length());repo.syncCloud(bridge(true,true));assertEquals(0,repo.store.pending("route").length());assertEquals(1,repo.store.routeRecords().length());}
 @Test public void olderCloudStateNeverResurrectsRemovedAttachmentOrRoute()throws Exception{JSONObject old=change(),deleted=RoutePlan.change("route:1","route",route(),true,old,1001);repo.store.saveRouteChanges(new JSONArray().put(deleted));repo.store.importRouteSnapshot(new JSONObject().put("route_schema_version",1).put("route_changes",new JSONArray().put(old)));assertTrue(repo.store.routeRecords().getJSONObject(0).getBoolean("deleted"));assertEquals(1,repo.store.pending("route").length());}
 @Test public void invalidCloudRouteDoesNotDestroyCachedOrQueuedWork()throws Exception{repo.store.saveRouteChanges(new JSONArray().put(change()));repo.store.importRouteSnapshot(new JSONObject().put("route_schema_version",1).put("route_changes",new JSONArray().put(new JSONObject())));assertEquals(1,repo.store.routeRecords().length());assertEquals(1,repo.store.pending("route").length());assertFalse(repo.store.get("status").optString("route_error").isEmpty());}
}
